/* @autogenerated */
package net.civeira.phylax.common.crypto;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mockStatic;

import java.security.NoSuchAlgorithmException;

import javax.crypto.Cipher;
import javax.crypto.Mac;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.MockedStatic;

@DisplayName("KeyRingSecretStorage")
class KeyRingSecretStorageUnitTest {
  private static final String CONTEXT = "access.test.secret#owner-1";

  @Test
  @DisplayName("Should use the first valid key when no current one is configured")
  void shouldDefaultToFirstKey() {
    // Arrange — a ring with invalid entries before the valid ones
    KeyRingSecretStorage storage =
        new KeyRingSecretStorage("no-separator, bad id!:x, k3:, k1:one, k2:two", "");

    // Act — seal a value
    String sealed = storage.seal("plain", CONTEXT);

    // Assert — the first valid key seals and the value round-trips
    assertTrue(sealed.startsWith(KeyRingSecretStorage.SEALED_PREFIX + "k1:"));
    assertFalse(storage.needsReseal(sealed));
    assertEquals("plain", storage.open(sealed, CONTEXT));
  }

  @Test
  @DisplayName("Should fall back to a generic key when none is configured")
  void shouldFallBackToGenericKey() {
    KeyRingSecretStorage storage = new KeyRingSecretStorage("", "");
    assertTrue(
        storage.seal("plain", CONTEXT).startsWith(KeyRingSecretStorage.SEALED_PREFIX + "k0:"));
  }

  @Test
  @DisplayName("Should reject a current key missing from the ring")
  void shouldRejectUnknownCurrentKey() {
    assertThrows(IllegalArgumentException.class, () -> new KeyRingSecretStorage("k1:one", "k9"));
  }

  @Test
  @DisplayName("Should refuse to open values that are not sealed with a known key")
  void shouldRefuseInvalidSealedValues() {
    KeyRingSecretStorage storage = new KeyRingSecretStorage("k1:one", "k1");
    assertThrows(IllegalArgumentException.class, () -> storage.open(null, CONTEXT));
    assertThrows(IllegalArgumentException.class, () -> storage.open("plain", CONTEXT));
    assertThrows(IllegalArgumentException.class, () -> storage.open("sealed:k1", CONTEXT));
    assertThrows(IllegalArgumentException.class, () -> storage.open("sealed:k9:AAAA", CONTEXT));
    IllegalArgumentException tooShort =
        assertThrows(IllegalArgumentException.class, () -> storage.open("sealed:k1:AAAA", CONTEXT));
    assertEquals("Malformed sealed secret", tooShort.getCause().getMessage());
  }

  @Test
  @DisplayName("Should detect sealed values only by prefix")
  void shouldDetectSealedValues() {
    assertFalse(KeyRingSecretStorage.isSealed(null));
    assertFalse(KeyRingSecretStorage.isSealed("plain"));
    assertTrue(KeyRingSecretStorage.isSealed("sealed:k1:AAAA"));
  }

  @Test
  @DisplayName("Should report cipher unavailability while sealing as an illegal state")
  void shouldWrapMissingCipher() {
    KeyRingSecretStorage storage = new KeyRingSecretStorage("k1:one", "k1");
    try (MockedStatic<Cipher> cipher = mockStatic(Cipher.class)) {
      cipher.when(() -> Cipher.getInstance(anyString()))
          .thenThrow(new NoSuchAlgorithmException("missing"));
      IllegalStateException ex =
          assertThrows(IllegalStateException.class, () -> storage.seal("plain", CONTEXT));
      assertEquals("Unable to seal secret", ex.getMessage());
    }
  }

  @Test
  @DisplayName("Should report HKDF unavailability as an illegal state")
  void shouldWrapMissingHkdf() {
    try (MockedStatic<Mac> mac = mockStatic(Mac.class)) {
      mac.when(() -> Mac.getInstance(anyString()))
          .thenThrow(new NoSuchAlgorithmException("missing"));
      IllegalStateException ex =
          assertThrows(IllegalStateException.class, () -> new KeyRingSecretStorage("k1:one", "k1"));
      assertEquals("HKDF-SHA256 is unavailable", ex.getMessage());
    }
  }
}
